declarations.type:
∀ {carrier : Type} {zero : carrier} {op : carrier → carrier → carrier} {leftId : ∀ (x : carrier), op zero x = x}
  {rightId : ∀ (x : carrier), op x zero = x} {assoc : ∀ (x y z : carrier), op (op x y) z = op x (op y z)}
  {carrier_1 : Type} {zero_1 : carrier_1} {op_1 : carrier_1 → carrier_1 → carrier_1}
  {leftId_1 : ∀ (x : carrier_1), op_1 zero_1 x = x} {rightId_1 : ∀ (x : carrier_1), op_1 x zero_1 = x}
  {assoc_1 : ∀ (x y z : carrier_1), op_1 (op_1 x y) z = op_1 x (op_1 y z)},
  { carrier := carrier, zero := zero, op := op, leftId := leftId, rightId := rightId, assoc := assoc } =
      { carrier := carrier_1, zero := zero_1, op := op_1, leftId := leftId_1, rightId := rightId_1, assoc := assoc_1 } →
    carrier = carrier_1 ∧ HEq zero zero_1 ∧ HEq op op_1
